#include "ENGINE/Source/Event/event_internal.h"
#include "ENGINE/Source/Event/cinputobserver.h"
#include "ENGINE/Source/Event/observer.h"
#include <algorithm>

void EventInitialize(unsigned,unsigned threads){ObserverInitialize();InputObserverInitialize();IEvtQueueInitialize();IEvtInputInitialize();IEvtSchedulerInitialize(threads);}void EventDestroy(){IEvtSchedulerDestroy();IEvtInputDestroy();IEvtQueueDestroy();InputObserverDestroy();ObserverDestroy();}
void EventDoMessageLoop(){IEvtSchedulerProcess();}void EventInitiateShutdown(){IEvtSchedulerShutdown();}HEVENTCONTEXT EventCreateContextEx(EventHandler a,EventHandler b,EventHandler c,unsigned idle,char flags){return IEvtSchedulerCreateContext(a,b,c,idle,flags);}void EventCreateContext(EventHandler a,EventHandler b,EventHandler c){EventCreateContextEx(a,b,c,a?1u:500u,0);}int EventIsContextInteractive(HEVENTCONTEXT h){return IEvtSchedulerIsContextInteractive(EventInternal::CurrentOr(h));}HEVENTCONTEXT EventGetCurrentContext(){return EventInternal::current;}
void EventSetContextIdleTime(unsigned t,HEVENTCONTEXT h){auto*c=EventInternal::Resolve(h);if(c)c->idleTime=t? t:1;}int EventGetContextIdleTime(HEVENTCONTEXT h){auto*c=EventInternal::Resolve(h);return c?static_cast<int>(c->idleTime):0;}int EventIsButtonDown(unsigned b){return IEvtQueueCheckSyncMouseState(EventInternal::current,static_cast<MOUSEBUTTON>(b));}int EventIsKeyDown(unsigned k){return IEvtQueueCheckSyncKeyState(EventInternal::current,static_cast<KEY>(k));}void EventPostClose(HEVENTCONTEXT h){EventPostCloseEx(h);}void EventPostCloseEx(HEVENTCONTEXT h){h=EventInternal::CurrentOr(h);auto*c=EventInternal::Resolve(h);if(c){std::lock_guard lock(c->mutex);if(!c->destroyed)c->closed=true;}}
void EventRegister(EventHandler h){EventRegisterEx(EVENT_ID_CAPTURECHANGED,h);}void EventRegisterEx(unsigned id,EventHandler h,void*p,float priority){IEvtQueueRegister(EventInternal::current,static_cast<EVENTID>(id),h,p,priority);}void EventUnregister(EVENTID id,EventHandler h){EventUnregisterEx(id,h);}void EventUnregisterEx(unsigned id,EventHandler h,void*p,unsigned flags){IEvtQueueUnregister(EventInternal::current,static_cast<EVENTID>(id),h,p,flags);}
int EventInputProcess(HEVENTCONTEXT h){int shutdown=0;return IEvtInputProcess(&shutdown,EventInternal::CurrentOr(h));}
